"""CDX inventory helpers: resumable, cutoff-bounded capture discovery."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass, asdict
from typing import Iterable, Optional

from . import config
from .http import GAP, OK, Fetcher, Response

DEFAULT_FIELDS = "urlkey,timestamp,original,mimetype,statuscode,digest,length,redirect"


@dataclass
class Capture:
    timestamp: str
    original: str
    statuscode: str = ""
    mimetype: str = ""
    digest: str = ""
    length: str = ""
    urlkey: str = ""
    redirect: str = ""
    source_query: str = ""

    @property
    def key(self) -> str:
        return f"{self.timestamp}|{normalize_url(self.original)}"

    def to_row(self) -> dict:
        d = asdict(self)
        return {k: v for k, v in d.items() if v}


def normalize_url(url: str) -> str:
    """Canonical comparison form: no scheme, no default port, lowercase host."""
    u = url.strip()
    for scheme in ("https://", "http://"):
        if u.lower().startswith(scheme):
            u = u[len(scheme):]
            break
    if u.startswith("//"):
        u = u[2:]
    host, _, path = u.partition("/")
    host = host.lower()
    if ":" in host:
        host = host.rsplit(":", 1)[0]
    path = path or "/"
    return f"{host}/{path}" if path != "/" else host


def within_cutoff(timestamp: str, cutoff: str = config.CUTOFF) -> bool:
    return isinstance(timestamp, str) and len(timestamp) >= 14 and timestamp <= cutoff


def parse_cdx_json(rows: list, source_query: str = "") -> list[Capture]:
    """CDX json output: first row is a header when fields are requested."""
    out: list[Capture] = []
    if not rows:
        return out
    header: Optional[list] = None
    first = rows[0]
    if first and isinstance(first[0], str) and first[0] in ("urlkey", "timestamp"):
        header = list(first)
        rows = rows[1:]
    for row in rows:
        if not isinstance(row, (list, tuple)) or not row:
            continue
        if header is None:
            header = DEFAULT_FIELDS.split(",")
            header = header[: len(row)]
        rec = dict(zip(header, [str(v) for v in row]))
        ts = rec.get("timestamp", "")
        if not within_cutoff(ts):
            continue
        out.append(
            Capture(
                timestamp=ts,
                original=rec.get("original", ""),
                statuscode=rec.get("statuscode", ""),
                mimetype=rec.get("mimetype", ""),
                digest=rec.get("digest", ""),
                length=rec.get("length", ""),
                urlkey=rec.get("urlkey", ""),
                redirect=rec.get("redirect", ""),
                source_query=source_query,
            )
        )
    return out


def cdx_query(fetcher: Fetcher, url: str, *, match: str = "prefix", limit: int = 10000,
              extra: Optional[dict] = None) -> tuple[list[Capture], Response]:
    """One CDX query. Returns captures and the raw response for diagnostics."""
    params = {
        "url": url,
        "matchType": match,
        "from": "19960101",
        "to": config.CUTOFF,
        "fl": DEFAULT_FIELDS,
        "limit": str(limit),
    }
    if extra:
        params.update(extra)
    resp = fetcher.cdx(params)
    if not resp.ok:
        return [], resp
    try:
        rows = resp.json()
    except Exception as exc:  # pragma: no cover - defensive
        resp.error = "http_error"
        resp.message = f"bad cdx json: {exc}"
        return [], resp
    return parse_cdx_json(rows, source_query=url), resp


def year_windows(start_year: int = 2007, end_year: int = 2019) -> list[str]:
    """Per-year `from` values so big inventories can resume after interruption."""
    return [f"{y}0101" for y in range(start_year, end_year + 1)]


class CaptureIndex:
    """Append-only JSONL capture inventory with a resumable manifest."""

    def __init__(self, path: str, manifest_path: str | None = None):
        self.path = path
        self.manifest_path = manifest_path or path + ".manifest.json"
        self._keys: set[str] = set()
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        if os.path.exists(path):
            with open(path, encoding="utf-8") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        rec = json.loads(line)
                    except Exception:
                        continue
                    self._keys.add(f"{rec.get('timestamp')}|{normalize_url(rec.get('original',''))}")
        self.manifest = self._load_manifest()

    def _load_manifest(self) -> dict:
        if os.path.exists(self.manifest_path):
            try:
                with open(self.manifest_path, encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                return {}
        return {"done": {}, "stats": {}}

    def save_manifest(self) -> None:
        tmp = self.manifest_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(self.manifest, fh, ensure_ascii=False, indent=2, sort_keys=True)
        os.replace(tmp, self.manifest_path)

    def query_done(self, name: str) -> bool:
        return bool(self.manifest.get("done", {}).get(name))

    def mark_done(self, name: str, info: dict | None = None) -> None:
        self.manifest.setdefault("done", {})[name] = info or {"at": _now()}
        self.save_manifest()

    def add(self, captures: Iterable[Capture]) -> int:
        new = 0
        with open(self.path, "a", encoding="utf-8") as fh:
            for cap in captures:
                if cap.key in self._keys:
                    continue
                self._keys.add(cap.key)
                fh.write(json.dumps(cap.to_row(), ensure_ascii=False) + "\n")
                new += 1
            fh.flush()
            os.fsync(fh.fileno())
        self.manifest.setdefault("stats", {})[os.path.basename(self.path)] = len(self._keys)
        self.save_manifest()
        return new

    def all(self) -> list[Capture]:
        out: list[Capture] = []
        if not os.path.exists(self.path):
            return out
        with open(self.path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except Exception:
                    continue
                out.append(
                    Capture(
                        timestamp=rec.get("timestamp", ""),
                        original=rec.get("original", ""),
                        statuscode=rec.get("statuscode", ""),
                        mimetype=rec.get("mimetype", ""),
                        digest=rec.get("digest", ""),
                        length=rec.get("length", ""),
                        urlkey=rec.get("urlkey", ""),
                        redirect=rec.get("redirect", ""),
                        source_query=rec.get("source_query", ""),
                    )
                )
        return out


def _now() -> str:
    import datetime

    return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds")

"""HTTP access to the Internet Archive with retries, backoff and rate limiting.

Error classification is deliberate: the recovery ledger must be able to tell a
*confirmed archive gap* apart from a *timeout*, a *throttle* or a *transport*
failure, because only the former means "stop trying for now".
"""
from __future__ import annotations

import random
import threading
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Optional
from urllib.parse import quote

from . import config

try:  # requests is the fast path; urllib is the offline fallback.
    import requests  # type: ignore
except Exception:  # pragma: no cover - exercised only on bare runners
    requests = None  # type: ignore


# --- failure classes ---------------------------------------------------------
GAP = "archive_gap"            # archive says it has nothing (404 / "not archived")
TIMEOUT = "timeout"            # bounded long timeout hit
THROTTLED = "throttled"        # 429 / 503 / explicit rate-limit page
TRANSPORT = "transport"        # DNS/reset/other network failure
HTTP_ERROR = "http_error"      # other non-200 status
CUTOFF_VIOLATION = "cutoff_violation"  # capture newer than the cutoff
BAD_BODY = "bad_body"          # body is not the media type we asked for
OK = "ok"


class RecoveryError(Exception):
    """Raised for unrecoverable configuration problems (never for gaps)."""

    def __init__(self, message: str, kind: str = TRANSPORT, status: int | None = None):
        super().__init__(message)
        self.kind = kind
        self.status = status


@dataclass
class Response:
    url: str
    status: int | None
    body: bytes = b""
    headers: dict = field(default_factory=dict)
    error: Optional[str] = None      # one of OK, GAP, TIMEOUT, ...
    message: str = ""
    elapsed: float = 0.0
    attempts: int = 1

    @property
    def ok(self) -> bool:
        return self.error == OK

    def text(self, encoding: str = "utf-8") -> str:
        return self.body.decode(encoding, errors="replace")

    def json(self) -> Any:
        import json

        return json.loads(self.text())


class RateLimiter:
    """Simple global minimum spacing between outbound requests."""

    def __init__(self, interval: float = config.MIN_REQUEST_INTERVAL):
        self.interval = interval
        self._last = 0.0
        self._lock = threading.Lock()

    def wait(self) -> None:
        with self._lock:
            now = time.monotonic()
            delay = self.interval - (now - self._last)
            if delay > 0:
                time.sleep(delay)
            self._last = time.monotonic()


class Fetcher:
    """Bounded, retrying HTTP GET. Subclass for offline tests."""

    def __init__(
        self,
        timeout: float = config.DEFAULT_TIMEOUT,
        attempts: int = config.MAX_ATTEMPTS,
        limiter: Optional[RateLimiter] = None,
        sleep: Callable[[float], None] = time.sleep,
    ):
        self.timeout = timeout
        self.attempts = attempts
        self.limiter = limiter if limiter is not None else RateLimiter()
        self.sleep = sleep
        self.session = requests.Session() if requests is not None else None
        if self.session is not None:
            self.session.headers.update({"User-Agent": config.USER_AGENT})
        self.stats: dict[str, int] = {}

    # -- to be provided by tests ------------------------------------------
    def _raw(self, url: str, timeout: float) -> Response:  # pragma: no cover
        raise NotImplementedError

    def _get(self, url: str, timeout: float) -> Response:
        if self.session is not None:
            start = time.monotonic()
            try:
                r = self.session.get(url, timeout=timeout, allow_redirects=True)
                return Response(
                    url=str(r.url),
                    status=r.status_code,
                    body=r.content,
                    headers={k.lower(): v for k, v in r.headers.items()},
                    elapsed=time.monotonic() - start,
                )
            except Exception as exc:  # requests raises many concrete types
                name = type(exc).__name__.lower()
                kind = TIMEOUT if "timeout" in name else TRANSPORT
                return Response(url=url, status=None, error=kind, message=str(exc)[:300])
        return self._urllib_get(url, timeout)

    def _urllib_get(self, url: str, timeout: float) -> Response:  # pragma: no cover
        import urllib.error
        import urllib.request

        req = urllib.request.Request(url, headers={"User-Agent": config.USER_AGENT})
        start = time.monotonic()
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                body = resp.read()
                return Response(
                    url=resp.geturl(),
                    status=resp.status,
                    body=body,
                    headers={k.lower(): v for k, v in resp.headers.items()},
                    elapsed=time.monotonic() - start,
                )
        except urllib.error.HTTPError as exc:
            body = b""
            try:
                body = exc.read()
            except Exception:
                pass
            return Response(url=url, status=exc.code, body=body, elapsed=time.monotonic() - start)
        except Exception as exc:
            name = type(exc).__name__.lower()
            kind = TIMEOUT if "timeout" in name else TRANSPORT
            return Response(url=url, status=None, error=kind, message=str(exc)[:300])

    # -- retry / classify --------------------------------------------------
    @staticmethod
    def classify(resp: Response) -> Response:
        if resp.error is not None and resp.error != OK:
            return resp
        status = resp.status or 0
        if status == 200:
            resp.error = OK
        elif status in (404, 410):
            resp.error = GAP
            resp.message = resp.message or f"HTTP {status}"
        elif status in (429, 503):
            resp.error = THROTTLED
            resp.message = resp.message or f"HTTP {status}"
        else:
            resp.error = HTTP_ERROR
            resp.message = resp.message or f"HTTP {status}"
        return resp

    def get(
        self,
        url: str,
        *,
        timeout: Optional[float] = None,
        attempts: Optional[int] = None,
        idempotent: bool = True,
    ) -> Response:
        timeout = self.timeout if timeout is None else timeout
        attempts = self.attempts if attempts is None else attempts
        last: Optional[Response] = None
        for attempt in range(1, max(1, attempts) + 1):
            self.limiter.wait()
            resp = self.classify(self._get(url, timeout))
            resp.attempts = attempt
            last = resp
            if resp.ok:
                break
            if not idempotent:
                break
            # Retry only transient classes; a gap or a cutoff violation is final.
            if resp.error in (GAP, CUTOFF_VIOLATION, BAD_BODY, HTTP_ERROR):
                break
            if attempt >= max(1, attempts):
                break
            delay = min(45.0, (2 ** (attempt - 1)) * 3.0) * (0.6 + random.random() * 0.8)
            self.sleep(delay)
        if last is not None:
            self.stats[last.error or "unknown"] = self.stats.get(last.error or "unknown", 0) + 1
        return last  # type: ignore[return-value]

    # -- Wayback-specific --------------------------------------------------
    @staticmethod
    def replay_url(timestamp: str, original: str, mode: str = "id_") -> str:
        """Wayback replay URL. `mode` id_=raw bytes, if_=iframe, ""=toolbar page."""
        if timestamp > config.CUTOFF:
            raise RecoveryError(
                f"capture {timestamp} is newer than cutoff {config.CUTOFF}",
                kind=CUTOFF_VIOLATION,
            )
        return f"{config.REPLAY_BASE}/{timestamp}{mode}/{original}"

    def replay(self, timestamp: str, original: str, mode: str = "id_", **kw) -> Response:
        try:
            url = self.replay_url(timestamp, original, mode)
        except RecoveryError as exc:
            return Response(url=original, status=None, error=exc.kind, message=str(exc))
        resp = self.get(url, **kw)
        resp.url = url
        resp.message = resp.message or ""
        # `id_` replays of missing captures answer with a 200 HTML error page.
        if resp.ok and resp.headers.get("content-type", "").startswith("text/html") and mode == "id_":
            body = resp.text()[:4000]
            if "has not been archived" in body or "does not have a page" in body or "not found" in body.lower()[:400]:
                resp.error = GAP
                resp.message = "replay returned 'not archived' HTML"
        return resp

    def cdx(self, params: dict, **kw) -> Response:
        from urllib.parse import urlencode

        query = dict(params)
        query.setdefault("output", "json")
        return self.get(f"{config.CDX_URL}?{urlencode(query, safe=':*/,')}", **kw)

"""GHCR (OCI registry v2) push for per-post artifacts.

Credentials come from the environment only (GITHUB_TOKEN / GHCR_USERNAME) and
are never written to disk, logs or artifacts.
"""
from __future__ import annotations

import json
import os
import time
from dataclasses import dataclass, field
from typing import Optional

from . import config, oci

try:
    import requests  # type: ignore
except Exception:  # pragma: no cover
    requests = None  # type: ignore


class AuthError(Exception):
    pass


class PublishError(Exception):
    pass


@dataclass
class PushResult:
    tag: str
    action: str            # pushed | updated | skipped | failed
    manifest_digest: str = ""
    reason: str = ""
    layers: list = field(default_factory=list)
    config_digest: str = ""
    image_count: int = 0
    missing_count: int = 0


def _auth() -> tuple[str, str]:
    user = os.environ.get("GHCR_USERNAME", "")
    token = os.environ.get("GITHUB_TOKEN", "")
    if not token:
        raise AuthError("GITHUB_TOKEN is not set in the environment")
    if not user:
        raise AuthError("GHCR_USERNAME is not set in the environment")
    return user, token


class Registry:
    """Tiny OCI distribution client: token auth, blob push, manifest push."""

    def __init__(self, repo: str = config.GHCR_REPO, registry: str = config.REGISTRY,
                 session=None, sleep=time.sleep):
        if requests is None:  # pragma: no cover
            raise AuthError("requests is required for registry access")
        self.registry = registry
        self.repo = repo
        self.sleep = sleep
        self.session = session or requests.Session()
        self._token: Optional[str] = None
        self._token_scope: Optional[str] = None

    # -- plumbing ----------------------------------------------------------
    def _basic(self):
        import base64

        user, token = _auth()
        raw = base64.b64encode(f"{user}:{token}".encode()).decode()
        return {"Authorization": "Basic " + raw}

    def _bearer(self, scope: str, force: bool = False) -> str:
        if not force and self._token and self._token_scope == scope:
            return self._token
        url = f"https://{self.registry}/token?service={self.registry}&scope={scope}"
        resp = self.session.get(url, headers=self._basic(), timeout=30)
        if resp.status_code != 200:
            raise AuthError(f"registry token request failed with HTTP {resp.status_code}")
        self._token = resp.json().get("token") or resp.json().get("access_token")
        self._token_scope = scope
        if not self._token:
            raise AuthError("registry token response had no token")
        return self._token

    def _headers(self, extra: Optional[dict] = None, retry: bool = True) -> dict:
        scope = f"repository:{self.repo}:pull,push"
        token = self._bearer(scope, force=retry)
        h = {"Authorization": "Bearer " + token}
        if extra:
            h.update(extra)
        return h

    def _request(self, method: str, url: str, *, headers: Optional[dict] = None,
                 data: Optional[bytes] = None, retries: int = 3, timeout: int = 180):
        last_exc: Optional[Exception] = None
        for attempt in range(retries):
            try:
                resp = self.session.request(method, url, headers=self._headers(headers),
                                            data=data, timeout=timeout)
            except Exception as exc:
                last_exc = exc
                self.sleep(2 * (attempt + 1))
                continue
            if resp.status_code in (401, 403) and attempt + 1 < retries:
                self._bearer(f"repository:{self.repo}:pull,push", force=True)
                continue
            if resp.status_code in (429, 500, 502, 503, 504) and attempt + 1 < retries:
                self.sleep(3 * (attempt + 1))
                continue
            return resp
        raise PublishError(f"{method} {url.split('?')[0]} failed after {retries} attempts: {last_exc}")

    # -- registry ops ------------------------------------------------------
    def _v2(self, path: str) -> str:
        return f"https://{self.registry}/v2/{self.repo}/{path}"

    def has_blob(self, digest: str) -> bool:
        resp = self.session.head(self._v2(f"blobs/{digest}"), headers=self._headers(), timeout=60,
                                 allow_redirects=False)
        return resp.status_code == 200

    def push_blob(self, blob: oci.Blob) -> str:
        if self.has_blob(blob.digest):
            return "exists"
        start = self._request("POST", self._v2("blobs/uploads/"), data=b"")
        if start.status_code not in (202,):
            raise PublishError(f"blob upload start failed with HTTP {start.status_code}")
        location = start.headers.get("location") or start.headers.get("Location")
        if not location:
            raise PublishError("blob upload start returned no Location header")
        if location.startswith("/"):
            location = f"https://{self.registry}{location}"
        sep = "&" if "?" in location else "?"
        url = f"{location}{sep}digest={blob.digest}"
        resp = self._request("PUT", url, headers={"Content-Type": blob.media_type}, data=blob.data)
        if resp.status_code not in (201, 202):
            raise PublishError(f"blob PUT failed with HTTP {resp.status_code}")
        return "pushed"

    def get_manifest(self, reference: str, accept: str = oci.MANIFEST_MEDIA_TYPE) -> Optional[dict]:
        resp = self.session.get(self._v2(f"manifests/{reference}"),
                                headers=self._headers({"Accept": f"{accept}, application/vnd.docker.distribution.manifest.v2+json"}),
                                timeout=60)
        if resp.status_code == 404:
            return None
        if resp.status_code != 200:
            raise PublishError(f"manifest GET failed with HTTP {resp.status_code}")
        try:
            return resp.json()
        except Exception as exc:
            raise PublishError(f"manifest JSON parse failed: {exc}")

    def tag_exists(self, tag: str) -> bool:
        return self.get_manifest(tag) is not None

    def push_manifest(self, manifest_blob: oci.Blob, tag: str) -> None:
        resp = self._request("PUT", self._v2(f"manifests/{tag}"),
                             headers={"Content-Type": oci.MANIFEST_MEDIA_TYPE},
                             data=manifest_blob.data)
        if resp.status_code not in (201, 202):
            raise PublishError(f"manifest PUT failed with HTTP {resp.status_code}: {resp.text[:300]}")

    def list_tags(self, limit: int = 100) -> list[str]:
        tags: list[str] = []
        url = self._v2("tags/list") + f"?n={limit}"
        while url:
            resp = self._request("GET", url)
            if resp.status_code != 200:
                break
            body = resp.json()
            tags.extend(body.get("tags") or [])
            link = resp.headers.get("link") or resp.headers.get("Link") or ""
            url = ""
            if 'rel="next"' in link:
                url = link.split(";")[0].strip("<> ")
                if url.startswith("/"):
                    url = f"https://{self.registry}{url}"
        return tags


def _image_count(manifest: dict) -> int:
    ann = (manifest or {}).get("annotations") or {}
    try:
        return int(ann.get("shurik.post.images", "-1"))
    except Exception:
        return -1


def publish_post(post: dict, registry: Registry, *, force: bool = False) -> PushResult:
    """Idempotent per-post publish: never regress an already-published artifact."""
    config_blob, layers, tag, manifest, manifest_blob = oci.build_artifact(post)
    missing = len(post.get("missing_images") or [])
    result = PushResult(tag=tag, action="", layers=[], config_digest=config_blob.digest,
                        image_count=len([i for i in post.get("images", []) if i.get("sha256")]),
                        missing_count=missing)

    existing = None
    try:
        existing = registry.get_manifest(tag)
    except PublishError:
        existing = None
    if existing is not None and not force:
        prev_images = _image_count(existing)
        prev_ann = (existing.get("annotations") or {})
        prev_digest = "sha256:" + __import__("hashlib").sha256(
            json.dumps(existing.get("annotations", {}), sort_keys=True).encode()).hexdigest()
        if prev_images == result.image_count and prev_ann.get("shurik.post.cutoff") == config.CUTOFF:
            result.action = "skipped"
            result.manifest_digest = prev_digest
            result.reason = "already published with the same recovered image count"
            return result
        result.action = "updated"

    for blob in [config_blob] + list(layers):
        registry.push_blob(blob)
        result.layers.append(blob.digest)
    registry.push_manifest(manifest_blob, tag)
    result.manifest_digest = manifest_blob.digest
    if not result.action:
        result.action = "pushed"
    return result


def package_page_url(tag: str) -> str:
    return f"https://github.com/users/{os.environ.get('GHCR_USERNAME', '')}/packages/container/package/{config.GHCR_REPO}?tag_name={tag}"


def parse_digest_header(value: str) -> str:
    for part in (value or "").split(";"):
        part = part.strip()
        if part.startswith("docker-content-digest="):
            return part.split("=", 1)[1]
    return ""

