    done = {r.get("media_url"): r for r in ledger.records()}
    media = JsonlStore(capture_file("media.jsonl"), key_fields=("timestamp", "original"))
    counts = {"proved_gap": 0, "capture_found": 0, "inconclusive": 0, "not_media": 0}
